import subprocess, json

def run(*args, stdin=None, cwd="/workspace"):
    import subprocess as sp
    r = sp.run(['/workspace/executable']+list(args), input=stdin, capture_output=True, text=True, cwd=cwd)
    return r

def bar_of(line):
    idx=[i for i,c in enumerate(line) if c=="\u2502"]
    return line[idx[-2]+1:idx[-1]] if len(idx)>=2 else ""

# Build deep chain programmatically
def make_chain(depth, start=100, step=5):
    node={"name":"l%d"%depth,"size":start-depth*step,"children":[]}
    for d in range(depth-1, -1, -1):
        name="root" if d==0 else "l%d"%d
        size=start-d*step
        node={"name":name,"size":size,"children":[node] if d!=depth else []}
        # Actually need to build correctly: start from leaf
    return node

# Simpler: build iteratively
leaf={"name":"l8","size":60,"children":[]}
cur=leaf
for i,d in enumerate([65,70,75,80,85,90,95]):
    name="l%d"%(7-i)
    cur={"name":name,"size":d,"children":[cur]}
root={"name":"root","size":100,"children":[cur]}
# root's child is l1? Let's see structure: root->l1(95)->l2(90)...->l8(60)
# Our cur after loop is l1? Check
import json as js
print(js.dumps(root)[:500])
j=json.dumps({"schema-version":"2024-11-02","unit":"bytes","tree":root})
r = run("--json-input", "--total-width=120", "--min-ratio=0", stdin=j)
print(r.stdout)
for line in r.stdout.splitlines():
    bar=bar_of(line)
    print(f"line {repr(line[:60])} counts E{bar.count(chr(0x2588))} S{bar.count(chr(0x2593))} M{bar.count(chr(0x2592))} L{bar.count(chr(0x2591))} sp{bar.count(' ')} len{len(bar)} set:{[hex(ord(c)) for c in set(bar) if ord(c)>127]}")
PY"}

