import subprocess, json
def run(*args, stdin=None, cwd="/workspace"):
    import subprocess as sp
    r = sp.run(['/workspace/executable']+list(args), input=stdin, capture_output=True, text=True, cwd=cwd)
    return r

# Rounding edge for metric/binary
for size in [999949, 999950, 9999499, 9999500, 1048575, 1048576]:
    for bf in ["metric","binary"]:
        tree={"name":"root","size":size,"children":[]}
        j=json.dumps({"schema-version":"2024-11-02","unit":"bytes","tree":tree})
        r = run("--json-input", f"--bytes-format={bf}", stdin=j)
        line=r.stdout.splitlines()[0]
        print(f"{size} {bf} => {repr(line.split(chr(0x250c))[0].strip() if chr(0x250c) in line else line[:20])} full {repr(line[:30])}")

print("===")
# Test truncation with long names
tree={"name":"root","size":100,"children":[{"name":"very_long_filename_that_exceeds_width","size":60,"children":[]},{"name":"short","size":40,"children":[]}]}
j=json.dumps({"schema-version":"2024-11-02","unit":"bytes","tree":tree})
for args in [["--total-width=80"], ["--column-width","20","20"], ["--column-width","10","10"]]:
    r = run("--json-input", *args, stdin=j)
    print(f"ARGS {args}")
    print(r.stdout)
    for line in r.stdout.splitlines():
        print(repr(line), "len", len(line))
