fn format_bytes(size: u64, fmt: BytesFormat) -> String {
    match fmt {
        BytesFormat::Plain => format!("{}", size),
        BytesFormat::Metric => {
            if size < 1000 {
                format!("{}   ", size)
            } else {
                // find unit
                let units = ["", "K", "M", "G", "T", "P"];
                let mut v = size as f64;
                let mut ui = 0;
                while v >= 1000.0 && ui < 5 {
                    v /= 1000.0;
                    ui += 1;
                }
                // format with one decimal
                // Need to handle rounding that would give 1000.0K? Original keeps 1000.0K for 999950? Yes it keeps, not promoting if original < threshold? Actually promotion is based on value, not rounded display. Our loop promotes based on value >=1000, so 999950/1000=999.95 (<1000? No, 999950>=1000? Wait 999950>=1000, so ui=1 (K), v=999.95. That's <1000, so stays K, displays 1000.0K? Actually 999.95 rounded to 1000.0K. Good. For 1004999, v=1004.999? Wait 1004999/1000=1004.999, which is >=1000, so loop would promote again? Our while condition checks v>=1000 after division? For 1004999: start v=1004999, ui=0, v>=1000 => v=1004.999, ui=1, check again v>=1000 => v=1.004999, ui=2 => displays 1.0M. Good. So loop works.
                // Format: one decimal
                format!("{:.1}{}", v, units[ui])
            }
        }
        BytesFormat::Binary => {
            if size < 1024 {
                format!("{}   ", size)
            } else {
                let units = ["", "K", "M", "G", "T", "P"];
                let mut v = size as f64;
                let mut ui = 0;
                while v >= 1024.0 && ui < 5 {
                    v /= 1024.0;
                    ui += 1;
                }
                format!("{:.1}{}", v, units[ui])
            }
        }
    }
}

