fn format_bytes(size: u64, fmt: BytesFormat) -> String {
    match fmt {
        BytesFormat::Plain => format!("{}", size),
        BytesFormat::Metric => {
            if size < 1000 {
                format!("{}   ", size)
            } else {
                // find unit
                let units = ["", "K", "M", "G", "T", "P"];
                let mut v = size as f64;
                let mut ui = 0;
                while v >= 1000.0 && ui < 5 {
                    v /= 1000.0;
                    ui += 1;
                }
                // format with one decimal
