                // Format: one decimal
                format!("{:.1}{}", v, units[ui])
            }
        }
        BytesFormat::Binary => {
            if size < 1024 {
                format!("{}   ", size)
            } else {
                let units = ["", "K", "M", "G", "T", "P"];
                let mut v = size as f64;
                let mut ui = 0;
                while v >= 1024.0 && ui < 5 {
