fn filter_tree(node: &mut DataNode, total: u64, max_depth: Option<u64>, min_ratio: f64, depth: u64) {
    let mut kept: Vec<DataNode> = Vec::new();
    for mut child in std::mem::take(&mut node.children) {
        let child_depth = depth + 1;
        let show_depth = match max_depth {
            None => true,
            Some(m) => child_depth < m,
        };
        let ratio = if total == 0 { 1.0 } else { child.size as f64 / total as f64 };
        let show_ratio = ratio >= min_ratio;
        if show_depth && show_ratio {
            filter_tree(&mut child, total, max_depth, min_ratio, child_depth);
            kept.push(child);
        }
    }
    node.children = kept;
}

fn to_json_tree(node: &DataNode) -> JsonTree {
    JsonTree { name: node.name.clone(), size: node.size, children: node.children.iter().map(to_json_tree).collect() }
}
fn from_json_tree(j: &JsonTree) -> DataNode {
    DataNode { name: j.name.clone(), size: j.size, children: j.children.iter().map(from_json_tree).collect() }
}

fn truncate_name(name: &str, max_width: usize) -> String {
    let w = display_width(name);
    if w <= max_width { return name.to_string(); }
    if max_width < 4 {
        return String::new();
    }
    let keep = max_width - 3;
    let mut cur = 0usize;
    let mut out = String::new();
    for ch in name.chars() {
        let cw = unicode_width::UnicodeWidthChar::width(ch).unwrap_or(0);
        if cur + cw > keep { break; }
        out.push(ch);
        cur += cw;
    }
    out.push_str("...");
    out
}
