fn make_bar(e: &DispEntry, total: u64, bar_width: usize, align_right: bool) -> String {
    if bar_width == 0 {
        return String::new();
    }
    if total == 0 {
        // all sizes 0? Then bar empty (spaces)? Earlier block-count with all 0 gave bar spaces (no solid). Good. So bar is all spaces.
        return " ".repeat(bar_width);
    }
    // Compute cumulative widths for path from root to node
    // path_sizes[0] = root size (=total), ..., path_sizes[last] = node size
    // For root itself (depth0, path len1), bar is all solid (since N==R)
    // For others, solid = round(N/R*B), then for each ancestor from parent up to root's child? Actually segments for each ancestor's extra.
    // Let's compute cumulative rounded widths for each size in path
    let mut cum: Vec<usize> = Vec::new();
    for &s in e.path_sizes.iter() {
        let w = ((s as f64 / total as f64) * bar_width as f64).round() as usize;
        // Clamp to bar_width
        let w = w.min(bar_width);
        cum.push(w);
    }
    // cum[0] should be bar_width (since s0==total => 100% => bar_width). Good (rounding may give bar_width).
    // For node at depth d with path len d+1 (root depth0 len1), solid = cum[last], segments for ancestors:
    // For i from last-1 down to 0? Actually segments: solid for node, then for each ancestor A at index i (0<=i<last), segment = cum[i] - cum[i+1] with shade based on depth of ancestor? Wait ancestor depth determines shade: ancestor at depth i (root depth0 => spaces, depth1 => ░, depth2 => ▒, >=3 => ▓)? Actually earlier we deduced shade based on ancestor depth (the larger node's depth): depth0 spaces, depth1 ░, depth2 ▒, >=3 ▓.
    // But what about node depth? For leaf at depth3 with ancestors depths 0,1,2? Actually path sizes: [R(100,depth0), A(80,depth1), B(60,depth2), N(40,depth3)]? Wait N depth3, ancestors depths 0,1,2. Shades: for A(depth1) extra uses ░, for B(depth2) extra uses ▒, for root extra uses spaces. Good. So shade based on ancestor depth (the larger node's depth).
    // For node itself (depth d), solid uses █ regardless of depth. Good.
    // Implement: bar_chars vec of length bar_width, initially spaces.
    // Fill solid [0..solid] with █ (for left-aligned) or [bar_width-solid..] for right-aligned? Actually for left-aligned, solid left, spaces right. For right-aligned, solid right, spaces left. Shades in between.
    // For left-aligned, bar from left to right: solid (0..solid), then for each ancestor from immediate parent outward? Actually order left to right is leaf to root: solid first, then parent extra, then grandparent extra, etc., spaces last. Good.
    // For our path [R,A,B,N] with cum [Bw, Aw, Bw2, Nw]? Actually cum[0]=Bw (root, full), cum[1]=Aw (for A), cum[2]=Bw2 (for B), cum[3]=Nw (for N). Solid = Nw. Parent extra (B->N) = Bw2 - Nw with shade of B (depth2 => ▒). Next extra (A->B) = Aw - Bw2 with shade of A (depth1 => ░). Next extra (R->A) = Bw - Aw with spaces.
    // Good.
    // Depths: need depths for each ancestor. Path depths: root depth0, A depth1, B depth2, N depth3. Good. Ancestor depths for shades: B depth2 => ▒, A depth1 => ░, R depth0 => spaces.
    // For deeper with ancestor depth>=3 => ▓.
    let b = bar_width;
    let n = e.path_sizes.len();
